From 6ca5230d0bcbc69fc8fc41bc13f7d855962ce86d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 22:55:45 +0100
Subject: [PATCH] applets/taskmanager: show Meta+number hints while Meta is
 held
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

Nothing showed which entry the Meta+1…9 shortcuts would activate. When
Meta is held for a moment, the task manager that handles those shortcuts
now shows a small number badge on each of its first nine entries.

BUG: 444281
---
 applets/taskmanager/CMakeLists.txt |  1 +
 applets/taskmanager/backend.cpp    | 54 ++++++++++++++++++++++++++----
 applets/taskmanager/backend.h      |  7 ++++
 applets/taskmanager/qml/Task.qml   | 11 ++++++
 applets/taskmanager/qml/main.qml   | 18 ++++++++++
 5 files changed, 84 insertions(+), 7 deletions(-)

diff --git a/applets/taskmanager/CMakeLists.txt b/applets/taskmanager/CMakeLists.txt
index 64f548de35..b0d42c5d73 100644
--- a/applets/taskmanager/CMakeLists.txt
+++ b/applets/taskmanager/CMakeLists.txt
@@ -49,6 +49,7 @@ target_link_libraries(org.kde.plasma.taskmanager PRIVATE
                       Plasma::ActivitiesStats
                       KF6::ConfigGui
                       KF6::GlobalAccel
+                      KF6::GuiAddons
                       KF6::I18n
                       KF6::KIOCore
                       KF6::KIOGui
diff --git a/applets/taskmanager/backend.cpp b/applets/taskmanager/backend.cpp
index 1005d2a981..c0cc15f734 100644
--- a/applets/taskmanager/backend.cpp
+++ b/applets/taskmanager/backend.cpp
@@ -14,6 +14,7 @@
 #include <KFileItem>
 #include <KFilePlacesModel>
 #include <KLocalizedString>
+#include <KModifierKeyInfo>
 #include <KNotificationJobUiDelegate>
 #include <KProtocolInfo>
 #include <KService>
@@ -29,6 +30,7 @@
 #include <QApplication>
 #include <QJsonArray>
 #include <QMenu>
+#include <QPointer>
 #include <QQuickItem>
 #include <QQuickWindow>
 #include <QStandardPaths>
@@ -73,11 +75,13 @@ Backend::Backend(QObject *parent)

     s_instances.append(this);
     setupShortcuts();
+    updateShowsTaskNumbers();
 }

 Backend::~Backend()
 {
     s_instances.removeAll(this);
+    updateShowsTaskNumbers();
 }

 int Backend::screen() const
@@ -103,6 +107,7 @@ void Backend::setHasActiveTask(bool active)
     if (m_hasActiveTask != active) {
         m_hasActiveTask = active;
         Q_EMIT hasActiveTaskChanged();
+        updateShowsTaskNumbers();
     }
 }

@@ -116,9 +121,15 @@ void Backend::setShowsOnlyCurrentScreen(bool shows)
     if (m_showsOnlyCurrentScreen != shows) {
         m_showsOnlyCurrentScreen = shows;
         Q_EMIT showsOnlyCurrentScreenChanged();
+        updateShowsTaskNumbers();
     }
 }

+bool Backend::showsTaskNumbers() const
+{
+    return m_showsTaskNumbers;
+}
+
 QUrl Backend::tryDecodeApplicationsUrl(const QUrl &launcherUrl)
 {
     if (launcherUrl.isValid() && launcherUrl.scheme() == QLatin1String("applications")) {
@@ -644,14 +655,13 @@ Backend *Backend::findTargetBackend()
     return fallback;
 }

-void Backend::dispatchActivateTaskAtIndex(int index)
+Backend *Backend::findActivateTaskAtIndexBackend()
 {
     // Prefer the same priority order as the other task shortcuts:
     // 1. Non-screen-filtered taskbar with the active task
     // 2. Screen-filtered taskbar with the active task
     if (auto *target = findTargetBackend()) {
-        Q_EMIT target->activateTaskAtIndexRequested(index);
-        return;
+        return target;
     }

     // If no task is active on any taskmanager (e.g. the user wants to
@@ -660,15 +670,45 @@ void Backend::dispatchActivateTaskAtIndex(int index)
     Backend *fallback = nullptr;
     for (auto *instance : std::as_const(s_instances)) {
         if (!instance->m_showsOnlyCurrentScreen) {
-            Q_EMIT instance->activateTaskAtIndexRequested(index);
-            return;
+            return instance;
         }
         if (!fallback) {
             fallback = instance;
         }
     }
-    if (fallback) {
-        Q_EMIT fallback->activateTaskAtIndexRequested(index);
+    return fallback;
+}
+
+void Backend::dispatchActivateTaskAtIndex(int index)
+{
+    if (auto *target = findActivateTaskAtIndexBackend()) {
+        Q_EMIT target->activateTaskAtIndexRequested(index);
+    }
+}
+
+void Backend::updateShowsTaskNumbers()
+{
+    static QPointer<KModifierKeyInfo> keyInfo;
+    if (s_instances.isEmpty()) {
+        return;
+    }
+    if (!keyInfo) {
+        keyInfo = new KModifierKeyInfo(qApp);
+        QObject::connect(keyInfo, &KModifierKeyInfo::keyPressed, keyInfo, [](Qt::Key key) {
+            if (key == Qt::Key_Meta) {
+                updateShowsTaskNumbers();
+            }
+        });
+    }
+
+    // Show the Meta+number hints on the task manager that would handle them
+    Backend *target = keyInfo->isKeyPressed(Qt::Key_Meta) ? findActivateTaskAtIndexBackend() : nullptr;
+    for (auto *instance : std::as_const(s_instances)) {
+        const bool shows = instance == target;
+        if (instance->m_showsTaskNumbers != shows) {
+            instance->m_showsTaskNumbers = shows;
+            Q_EMIT instance->showsTaskNumbersChanged();
+        }
     }
 }

