--- a/applets/taskmanager/qml/main.qml
+++ b/applets/taskmanager/qml/main.qml
@@ -87,6 +87,9 @@ PlasmoidItem {
     }
 //END TODO

+    // Meta+number hints, shown once Meta has been held for a moment
+    property bool showTaskNumbers: false
+
     property Item dragSource
     property var hoveredWinIds

@@ -267,6 +270,21 @@ PlasmoidItem {
         onMoveActiveTaskForwardRequested: () => {
             tasks.moveActiveTaskForward();
         }
+
+        onShowsTaskNumbersChanged: () => {
+            tasks.showTaskNumbers = false;
+            if (showsTaskNumbers) {
+                taskNumbersTimer.restart();
+            } else {
+                taskNumbersTimer.stop();
+            }
+        }
+    }
+
+    Timer {
+        id: taskNumbersTimer
+        interval: Kirigami.Units.toolTipDelay
+        onTriggered: tasks.showTaskNumbers = true
     }

     DBus.DBusServiceWatcher {
